import threading

class Foo:
    def __init__(self):
        self.done1 = threading.Event()
        self.done2 = threading.Event()

    def first(self, printFirst):
        printFirst()
        self.done1.set()

    def second(self, printSecond):
        self.done1.wait()
        printSecond()
        self.done2.set()

    def third(self, printThird):
        self.done2.wait()
        printThird()

